void ui_event_weather(lv_event_t *e)
{
    lvgl_port_lock(0);
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_obj_t *target = lv_event_get_target(e);
    if (event_code == LV_EVENT_SCREEN_LOAD_START)
    {

        // riseup_Animation(ui_weather_hour, 0);
        // riseup_Animation(ui_weather_min, 0);
        // // weather_Animation(ui_weather_weathershow, 0);
        // opaon_Animation(ui_weather_weather, 0);
        // opaon_Animation(ui_weather_temp, 0);
        // opaon_Animation(ui_weather_weekday, 0);
        // opaon_Animation(ui_weather_date, 0);
        // falldown_Animation(ui_title_page, 0);
        lv_obj_set_parent(ui_title_page, ui_weather_page);
    }
    if (event_code == LV_EVENT_RIGHT_CLICK)
    {
        _ui_screen_change(&ui_face_screen, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_face_screen_init);
    }
    if (event_code == LV_EVENT_LEFT_CLICK)
    {
        //_ui_screen_change(&ui_camera_screen, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_camera_screen_init);
         _ui_screen_change(&ui_game_screen, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_game_screen_init);
    }
    if (event_code == LV_EVENT_UP_LONG_CLICK || event_code == LV_EVENT_DOWN_LONG_CLICK)
    {
        uint8_t event_code = UI_EVENT_WIFI_AP_MODE; // ap配网模式
        xQueueSend(ui_send_event, &event_code, 0);
    }
    lvgl_port_unlock();
}
